import {R211ExteriorSideRenderer,frameText,layoutText} from './displays/r211-side/engine.js?v=25';
import {preset,uid,validateProject} from './state.js?v=24';
import {normalizeRouteLabel,isSupportedRouteLabel} from './displays/r211-side/route-glyphs.js?v=24';
import {download,canvasBlob,recordedVideo} from './export.js?v=25';
import {syncBoundFrames,fitText,migrateText} from './editor-model.js?v=25';
const $=id=>document.getElementById(id),renderer=new R211ExteriorSideRenderer();let project=preset(),index=0,playing=false,timer=null,loops=0;try{const saved=localStorage.getItem('r211-v1');if(saved){const restored=JSON.parse(saved);if(restored.route&&!isSupportedRouteLabel(restored.route.label))restored.route.label=normalizeRouteLabel(restored.route.label)||'A';project=validateProject(restored);}}catch{}
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const frame=()=>project.frames[index];
function toast(msg){$('toast').textContent=msg;$('toast').style.display='block';setTimeout(()=>$('toast').style.display='none',4500)}
function persist(){try{localStorage.setItem('r211-v1',JSON.stringify(project));$('saved').textContent='● Saved locally';}catch{$('saved').textContent='Local save unavailable';}}
function pause(){playing=false;clearTimeout(timer);$('play').textContent='▶ Play'}
function schedule(){clearTimeout(timer);if(!playing)return;timer=setTimeout(()=>{index++;if(index>=project.frames.length){loops++;const max=project.animation.loop==='infinite'?Infinity:project.animation.loop==='once'?1:project.animation.count;if(loops>=max){index=project.frames.length-1;pause();render();return;}index=0;}render();schedule()},(frame().duration??project.defaultDuration)*1000)}
function update(full=false){syncBoundFrames(project);persist();if(full)sync();render();if(playing)schedule()}
function render(){index=Math.min(index,project.frames.length-1);const f=frame();const l=renderer.renderFrame($('preview'),project,f,previewOptions());let warnings=[];if(l.overflow)warnings.push('Text exceeds this matrix. Edit wording or create additional frames; exports are disabled until every frame fits.');if(l.unsupported.length)warnings.push(`Unsupported characters: ${l.unsupported.join(' ')}. Replace them with characters in the glyph inspector.`);$('warning').textContent=warnings.join(' ');$('resolved-text').textContent=frameText(project,f).toUpperCase();$('frame-number').textContent=`FRAME ${String(index+1).padStart(2,'0')} / ${String(project.frames.length).padStart(2,'0')}`;$('total').textContent=`${project.frames.length} frames · ${project.frames.reduce((n,f)=>n+(f.duration??project.defaultDuration),0).toFixed(1)}s`;renderTimeline();syncFrame();}
function sync(){const p=project;$('route-label').value=p.route.label;$('color').value=p.route.color;$('hex').value=p.route.color;$('shape').value=p.route.shape;$('destination').value=p.destination;$('default-duration').value=p.defaultDuration;$('loop').value=p.animation.loop;$('loop-count').value=p.animation.count??3;$('loop-count-wrap').hidden=p.animation.loop!=='custom';renderDescriptions();syncBackground();}
function syncFrame(){const f=frame();if(document.activeElement!==$('duration'))$('duration').value=f.duration??project.defaultDuration;$('duration').disabled=f.duration==null;$('use-default').checked=f.duration==null;}
function renderTimeline(){$('timeline').innerHTML=project.frames.map((f,i)=>`<article class="frame-card ${i===index?'active':''}" data-index="${i}" tabindex="0" aria-label="Select frame ${i+1}"><div class="card-meta"><span>FRAME ${String(i+1).padStart(2,'0')}</span><span>${(f.duration??project.defaultDuration).toFixed(1)}s</span></div><h3>${esc(frameText(project,f).toUpperCase())||'EMPTY FRAME'}</h3><small>${i===0?'destination':'route description / via'}</small></article>`).join('')}
function move(list,from,to){if(to<0||to>=list.length)return;const [item]=list.splice(from,1);list.splice(to,0,item)}
$('timeline').onclick=e=>{const card=e.target.closest('.frame-card');if(card){pause();index=Number(card.dataset.index);render()}};
$('timeline').onkeydown=e=>{if(e.key==='Enter'&&e.target.classList.contains('frame-card')){index=Number(e.target.dataset.index);pause();render()}};
function renderDescriptions(){$('descriptions').innerHTML=project.routeDescriptions.map((d,i)=>`<div class="description" data-index="${i}"><textarea rows="2" spellcheck="false" aria-label="Route description ${i+1}" aria-describedby="text-limit">${esc(d.text)}</textarea><div class="mini-actions"><button data-act="up" title="Move up" ${i===0?'disabled':''}>↑</button><button data-act="down" title="Move down" ${i===project.routeDescriptions.length-1?'disabled':''}>↓</button><button data-act="duplicate">Duplicate</button><button data-act="delete" title="Delete description">×</button></div></div>`).join('')}
function limitText(el){const text=fitText(el.value,project.style);if(text!==el.value.toUpperCase().replaceAll('\r',''))toast('Maximum two lines; each line must fit the LED panel.');if(el.value!==text){const cursor=el.selectionStart;el.value=text;el.setSelectionRange(Math.min(cursor,text.length),Math.min(cursor,text.length));}return text;}
$('descriptions').oninput=e=>{if(e.target.tagName!=='TEXTAREA')return;const i=Number(e.target.closest('.description').dataset.index);project.routeDescriptions[i].text=limitText(e.target);update()};
$('descriptions').onclick=e=>{if(!e.target.dataset.act)return;const i=Number(e.target.closest('.description').dataset.index),act=e.target.dataset.act;syncBoundFrames(project);if(act==='duplicate'&&project.routeDescriptions.length>=99){toast('Maximum 100 frames.');return;}if(act==='delete')project.routeDescriptions.splice(i,1);else if(act==='duplicate'&&project.routeDescriptions.length<99)project.routeDescriptions.splice(i+1,0,{...project.routeDescriptions[i],id:uid()});else move(project.routeDescriptions,i,i+(act==='up'?-1:1));pause();update(true)};
$('add-desc').onclick=()=>{if(project.routeDescriptions.length>=99){toast('Maximum 100 frames.');return;}project.routeDescriptions.push({id:uid(),text:'VIA 63 ST'});update(true)};
function bind(id,fn,event='input'){$(id).addEventListener(event,e=>{fn(e.target);update()})}
bind('route-label',el=>{project.route.label=normalizeRouteLabel(el.value);el.value=project.route.label;});bind('shape',el=>project.route.shape=el.value,'change');bind('color',el=>{project.route.color=el.value;$('hex').value=el.value});bind('hex',el=>{if(/^#[0-9a-f]{6}$/i.test(el.value)){project.route.color=el.value;$('color').value=el.value;el.setCustomValidity('')}else el.setCustomValidity('Use six hex digits, for example #0039A6')});bind('destination',el=>project.destination=limitText(el));bind('duration',el=>{if(el.value!==''&&el.checkValidity())frame().duration=Number(el.value)},'input');bind('use-default',el=>{if(el.checked)delete frame().duration;else frame().duration=project.defaultDuration},'change');bind('default-duration',el=>{if(el.checkValidity()&&el.value)project.defaultDuration=Number(el.value)},'input');bind('loop',el=>{project.animation.loop=el.value;$('loop-count-wrap').hidden=el.value!=='custom'},'change');bind('loop-count',el=>{if(el.checkValidity()&&el.value)project.animation.count=Number(el.value)},'input');
$('preset').onchange=e=>{if(!e.target.value)return;pause();const background=structuredClone(backgroundSettings());project=preset(e.target.value);project.background=background;migrateText(project);syncBoundFrames(project);index=0;update(true)};
const colors={'8 Avenue':'#0039A6','6 Avenue':'#FF6319','Broadway':'#FCCC0A','Lexington':'#00933C','7 Avenue':'#EE352E','Flushing':'#B933AD','Shuttle':'#808183'};$('swatches').innerHTML=Object.entries(colors).map(([n,c])=>`<button title="${n}" aria-label="${n} color" data-color="${c}" style="background:${c}"></button>`).join('');$('swatches').onclick=e=>{if(e.target.dataset.color){project.route.color=e.target.dataset.color;update(true)}};
function backgroundSettings(){return project.background??= {mode:'physical',color:'#20282d',customUnlit:false,transparentUnlit:false};}
function previewOptions(){const b=backgroundSettings();return {physical:b.mode==='physical',backgroundColor:b.mode==='custom'?b.color:null,showUnlit:b.mode==='physical'||(b.mode==='custom'?b.customUnlit:b.transparentUnlit)};}
function exportOptions(){return previewOptions();}
function videoOptions(){const b=backgroundSettings(),mode=$('video-background').value;return {physical:mode==='physical',backgroundColor:mode==='green'?'#00ff00':mode==='custom'?b.color:null,showUnlit:mode==='physical'||(mode==='custom'&&b.customUnlit)};}
function syncBackground(){const b=backgroundSettings();$('stage').className='preview-stage '+b.mode;$('stage').style.backgroundColor=b.mode==='custom'?b.color:'';$('background-color').value=b.color;$('custom-unlit').checked=b.customUnlit;$('transparent-unlit').checked=b.transparentUnlit;for(const button of $('backgrounds').querySelectorAll('[data-bg]')){const active=button.dataset.bg===b.mode;button.classList.toggle('active',active);button.setAttribute('aria-pressed',String(active));}}
$('backgrounds').onclick=e=>{const button=e.target.closest('button[data-bg]');if(button){backgroundSettings().mode=button.dataset.bg;syncBackground();update();}};
bind('background-color',el=>{const b=backgroundSettings();b.color=el.value;b.mode='custom';syncBackground();});
bind('custom-unlit',el=>backgroundSettings().customUnlit=el.checked,'change');
bind('transparent-unlit',el=>backgroundSettings().transparentUnlit=el.checked,'change');
$('play').onclick=()=>{if(playing)pause();else{playing=true;loops=0;$('play').textContent='Ⅱ Pause';schedule()}};$('restart').onclick=()=>{index=0;loops=0;render();schedule()};$('prev').onclick=()=>{pause();index=(index+project.frames.length-1)%project.frames.length;render()};$('next').onclick=()=>{pause();index=(index+1)%project.frames.length;render()};
function checkExport(all){if(!isSupportedRouteLabel(project.route.label))throw Error('Enter one uppercase letter or one/two digits.');for(const f of all?project.frames:[frame()]){const v=renderer.validateContent(project,f,project.style);if(v.overflow||v.unsupported.length)throw Error('A frame contains overflowing or unsupported text. Edit the wording, split lines or create more frames first.')}}
$('png').onclick=async()=>{try{checkExport(false);download(await canvasBlob(renderer.exportFrame(project,frame(),4,exportOptions())),`R211-${project.route.label}-frame-${index+1}.png`);toast('PNG exported.')}catch(e){toast(e.message)}};
$('animation').onclick=async()=>{const button=$('animation');try{checkExport(true);button.disabled=true;const result=await recordedVideo(renderer,structuredClone(project),4,videoOptions(),(i,n)=>button.textContent=`Recording ${i}/${n}…`);download(result.blob,`R211-${project.route.label}-sequence.${result.extension}`);toast('Video exported: one complete cycle.')}catch(e){toast(e.message)}finally{button.disabled=false;button.textContent='↓ Video'}};
migrateText(project);syncBoundFrames(project);persist();sync();render();
